\begin{lemma}[Formalization support for symmetry of a typed CL distribution]\label{lem:typed-cl-distribution-symm}
	\lean{MIPStarRE.QPBT.typedCLDistribution_symm}
	\leanok
	\uses{def:typed-cl-distributions, def:graph-distribution, def:cl-dist}
	This is not a named statement of the source article; it records the symmetry that the source uses when it presents a typed game built from a single family as a symmetric game. Let $L$ be a $\mathcal T$-typed family of conditionally linear functions on $V$ and let $G = (\mathcal T, E)$ have nonempty edge set $E$. Then
	\[
		\mu^G_{L,\,L}\bigl((u, x), (v, y)\bigr) = \mu^G_{L,\,L}\bigl((v, y), (u, x)\bigr)
	\]
	for all types $u, v \in \mathcal T$ and all $x, y \in V$.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:graph-distribution-symm, def:cl-dist}
	Conditioned on the type pair $(u,v)$, the mass of $\bigl((u,x),(v,y)\bigr)$ is the number of seeds $z \in V$ with $L_u(z) = x$ and $L_v(z) = y$, divided by $|V|$; that count is unchanged when the two coordinates are exchanged together with the two types. Reindexing the sum over type pairs by the exchange $(u,v) \mapsto (v,u)$ and applying Lemma~\ref{lem:graph-distribution-symm} to the edge law gives the claim.
\end{proof}

